begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) values('af100000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','f1-owner@example.test',now(),now(),now()),('af100000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','f1-secretary@example.test',now(),now(),now());
insert into public.organizations(id,name,slug,status) values('bf100000-0000-4000-8000-000000000001','F1 A','f1-synthetic-a','active'),('bf100000-0000-4000-8000-000000000002','F1 B','f1-synthetic-b','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values('cf100000-0000-4000-8000-000000000001','bf100000-0000-4000-8000-000000000001','Sede F1','sede','headquarters'),('cf100000-0000-4000-8000-000000000002','bf100000-0000-4000-8000-000000000002','Sede F1 B','sede','headquarters');
insert into public.organization_memberships(organization_id,user_id,role,status,default_unit_id) values('bf100000-0000-4000-8000-000000000001','af100000-0000-4000-8000-000000000001','owner','active','cf100000-0000-4000-8000-000000000001'),('bf100000-0000-4000-8000-000000000001','af100000-0000-4000-8000-000000000002','secretary','active','cf100000-0000-4000-8000-000000000001');
insert into public.people(id,organization_id,unit_id,full_name) values('ef100000-0000-4000-8000-000000000001','bf100000-0000-4000-8000-000000000001','cf100000-0000-4000-8000-000000000001','Membro sintético F1');
select ok(not has_table_privilege('authenticated','private.finance_entries','SELECT'),'nenhuma leitura direta financeira');
select ok(not has_table_privilege('service_role','private.finance_entries','INSERT'),'serviço não contorna comandos');
select ok(not has_function_privilege('anon','public.finance_f1(uuid,uuid[],text,jsonb)','EXECUTE'),'visitante sem RPC');
select ok(not has_function_privilege('authenticated','private.post_church_journal(uuid,uuid,uuid,date,text,jsonb,uuid)','EXECUTE'),'postagem interna não exposta ao cliente');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"af100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('f1.org','bf100000-0000-4000-8000-000000000001',true);
select set_config('f1.unit','cf100000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'catalog','{"id":"df100000-0000-4000-8000-000000000001","kind":"account","name":"Caixa teste"}')$$,'cria conta real');
select lives_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'catalog','{"id":"df100000-0000-4000-8000-000000000002","kind":"category","name":"Ofertas teste","direction":"income","shared":true}')$$,'cria categoria compartilhada');
select set_config('f1.post',jsonb_build_object('id','ff100000-0000-4000-8000-000000000001','kind','income','amountCents','10000','description','Oferta sintética','account','df100000-0000-4000-8000-000000000001','category','df100000-0000-4000-8000-000000000002','competence',current_date,'due',current_date,'paid',current_date,'method','cash','person','ef100000-0000-4000-8000-000000000001','party','Nome forjado')::text,true);
select lives_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'entry',current_setting('f1.post')::jsonb)$$,'lançamento vinculado');
select lives_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'entry',current_setting('f1.post')::jsonb)$$,'reenvio não duplica');
select set_config('f1.query',jsonb_build_object('from',current_date,'to',current_date,'page',1)::text,true);
select is(public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'snapshot',current_setting('f1.query')::jsonb)->>'total','1','uma movimentação');
select is(public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'snapshot',current_setting('f1.query')::jsonb)#>>'{entries,0,party_name}','Membro sintético F1','nome canônico do membro');
select is(public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'snapshot',current_setting('f1.query')::jsonb)#>>'{summary,income}','10000','receita em centavos');
select is(public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'snapshot',current_setting('f1.query')::jsonb)#>>'{accounts,0,balanceCents}','10000','saldo real balanceado');
select throws_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'entry',jsonb_set(current_setting('f1.post')::jsonb,'{amountCents}','"20000"'))$$,'22023',null,'UUID não aceita conteúdo adulterado');
select throws_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array['cf100000-0000-4000-8000-000000000002'::uuid],'snapshot',current_setting('f1.query')::jsonb)$$,'42501',null,'não atravessa ministérios');
select throws_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid,current_setting('f1.unit')::uuid],'snapshot',current_setting('f1.query')::jsonb)$$,'22023',null,'não duplica unidades na consolidação');
select lives_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'entry',(current_setting('f1.post')::jsonb-'paid'-'person')||'{"id":"ff100000-0000-4000-8000-000000000002","party":"Sem cadastro"}')$$,'previsto sem vínculo');
select is(public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'snapshot',current_setting('f1.query')::jsonb)#>>'{summary,receivable}','10000','previsto separado');
select is(public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'snapshot',current_setting('f1.query')::jsonb)#>>'{accounts,0,balanceCents}','10000','previsto não infla caixa');
select lives_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'void',jsonb_build_object('id','ff100000-0000-4000-8000-000000000001','version',1,'reason','Correção sintética','date',current_date,'requestId','ff100000-0000-4000-8000-000000000003'))$$,'estorno real preserva original');
select is(public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'snapshot',current_setting('f1.query')::jsonb)#>>'{accounts,0,balanceCents}','0','estorno neutraliza caixa');
select is(public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'snapshot',current_setting('f1.query')::jsonb)#>>'{summary,income}','0','relatório considera estorno');
select throws_ok($$select public.post_church_journal(current_setting('f1.org')::uuid,current_setting('f1.unit')::uuid,'ff100000-0000-4000-8000-000000000009',current_date,'Contorno negado','[]','ff100000-0000-4000-8000-000000000001')$$,'42501',null,'rota antiga não estorna movimento do F1');
select lives_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'void',jsonb_build_object('id','ff100000-0000-4000-8000-000000000001','version',1,'reason','Correção sintética','date',current_date,'requestId','ff100000-0000-4000-8000-000000000003'))$$,'reenvio do estorno não duplica');
select throws_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'catalog','{"id":"df100000-0000-4000-8000-000000000001","kind":"account","name":"Outra conta","version":100}')$$,'40001',null,'versão futura não contorna concorrência');
select lives_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'catalog','{"id":"df100000-0000-4000-8000-000000000003","kind":"account","name":"Banco teste"}')$$,'segunda conta');
select lives_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'entry',(current_setting('f1.post')::jsonb-'person')||'{"id":"ff100000-0000-4000-8000-000000000004","kind":"transfer","category":"","destination":"df100000-0000-4000-8000-000000000003"}')$$,'transferência interna balanceada');
select is(public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'snapshot',current_setting('f1.query')::jsonb)#>>'{summary,income}','0','transferência não vira receita');
select throws_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'entry',current_setting('f1.post')::jsonb||'{"id":"ff100000-0000-4000-8000-000000000005","kind":"expense"}')$$,'22023',null,'categoria de entrada não classifica saída');
select lives_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'entry',(current_setting('f1.post')::jsonb-'person')||'{"id":"ff100000-0000-4000-8000-000000000006","kind":"opening","category":""}')$$,'abertura balanceada');
select throws_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'entry',(current_setting('f1.post')::jsonb-'person')||'{"id":"ff100000-0000-4000-8000-000000000007","kind":"opening","category":""}')$$,'23505',null,'abertura não se duplica por conta');
select is(public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'snapshot',current_setting('f1.query')::jsonb)#>>'{summary,income}','0','abertura não infla receita');
select lives_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'catalog','{"id":"df100000-0000-4000-8000-000000000002","kind":"category","name":"Ofertas teste","direction":"income","shared":true,"active":false,"version":1}')$$,'arquiva categoria sem apagar histórico');
select throws_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'entry',current_setting('f1.post')::jsonb||'{"id":"ff100000-0000-4000-8000-000000000008"}')$$,'22023',null,'categoria arquivada não recebe novos lançamentos');
select ok(private.finance_file_allowed('bf100000-0000-4000-8000-000000000001/cf100000-0000-4000-8000-000000000001/ff100000-0000-4000-8000-000000000001/ff100000-0000-4000-8000-000000000001.pdf'),'anexo financeiro autorizado');
select ok(not private.finance_file_allowed('bf100000-0000-4000-8000-000000000001/cf100000-0000-4000-8000-000000000002/ff100000-0000-4000-8000-000000000001/ff100000-0000-4000-8000-000000000001.pdf'),'anexo de unidade forjada negado');
select ok(not private.finance_file_allowed('../secret.pdf'),'path traversal negado');
select set_config('request.jwt.claims','{"sub":"af100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.finance_f1(current_setting('f1.org')::uuid,array[current_setting('f1.unit')::uuid],'snapshot',current_setting('f1.query')::jsonb)$$,'42501',null,'secretaria sem acesso financeiro');
reset role;
select ok((select not public and file_size_limit=4194304 from storage.buckets where id='finance-documents-private'),'bucket privado com limite');
select is((select sum(delta_cents) from public.church_ledger_lines where organization_id='bf100000-0000-4000-8000-000000000001'),0::numeric,'livro balanceado');
select * from finish();
rollback;
